import{_ as t,o,c as a,ag as s}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Lakehouse Tables","description":"","frontmatter":{},"headers":[],"relativePath":"sheets/lakehouse.md","filePath":"sheets/lakehouse.md"}'),r={name:"sheets/lakehouse.md"};function n(i,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="lakehouse-tables" tabindex="-1">Lakehouse Tables <a class="header-anchor" href="#lakehouse-tables" aria-label="Permalink to &quot;Lakehouse Tables&quot;">​</a></h1><p>A <strong>Lakehouse</strong> tab reads an open-table-format table sitting in object storage — Apache Iceberg or Delta Lake — straight into a read-only grid, without a database server in between. It also gives you a <strong>time-travel slider</strong> over the table&#39;s own commit history, so you can look at the table as it was at an earlier commit.</p><p>Lakehouse connections live alongside database connections; see <a href="./datasources.html">External Datasources</a> for the SQL side of the feature.</p><h2 id="create-a-lakehouse-tab" tabindex="-1">Create a Lakehouse Tab <a class="header-anchor" href="#create-a-lakehouse-tab" aria-label="Permalink to &quot;Create a Lakehouse Tab&quot;">​</a></h2><ol><li>Click the <strong>+</strong> at the end of the tab bar and choose <strong>New Lakehouse</strong>.</li><li>The <strong>Select Lakehouse</strong> dialog lists the Lakehouse connections your workspace already has. Click one to select it and click <strong>Select</strong> (double-clicking a connection does both), or click <strong>New Connection</strong> to set one up.</li></ol><p>The new tab is named after the connection and carries a warehouse icon.</p><h2 id="set-up-a-connection" tabindex="-1">Set Up a Connection <a class="header-anchor" href="#set-up-a-connection" aria-label="Permalink to &quot;Set Up a Connection&quot;">​</a></h2><p><strong>New Lakehouse Connection</strong> asks for:</p><ul><li><strong>Name</strong> — a label for the connection.</li><li><strong>Table format</strong> — <strong>Apache Iceberg</strong> or <strong>Delta Lake</strong>.</li><li><strong>Storage</strong> — where the table lives (see below).</li><li><strong>Bucket</strong> (labelled <strong>Container</strong> for Azure) and, for the S3 backends, <strong>Region</strong> (defaults to <code>us-east-1</code>).</li><li><strong>Endpoint</strong> — required for S3-compatible storage, optional for Azure.</li><li>The table path itself, labelled <strong>Iceberg metadata file (.metadata.json)</strong> or <strong>Delta table root</strong> depending on the format you picked.</li><li>Credentials for the storage backend.</li></ul><p>Click <strong>Test Connection</strong> to check it without saving, then <strong>Save</strong>.</p><h3 id="storage-backends" tabindex="-1">Storage backends <a class="header-anchor" href="#storage-backends" aria-label="Permalink to &quot;Storage backends&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Storage</th><th>What it needs</th></tr></thead><tbody><tr><td>Amazon S3</td><td>Bucket, Region, <strong>Access key</strong> + <strong>Secret key</strong>, optional <strong>Session token</strong></td></tr><tr><td>S3-compatible</td><td>Bucket, Region, an <strong>Endpoint</strong> (<code>http://</code> or <code>https://</code>, host only — no path), <strong>Access key</strong> + <strong>Secret key</strong>, optional <strong>Session token</strong></td></tr><tr><td>Google Cloud Storage</td><td>Bucket, <strong>Access key</strong> + <strong>Secret key</strong> — these are GCS <em>interoperability</em> HMAC keys, not a Google OAuth token</td></tr><tr><td>Azure Blob / ADLS</td><td>Container, an optional <strong>Custom endpoint</strong>, and either a <strong>Connection string</strong> on its own or an <strong>Account name</strong> with an <strong>Account key</strong> <em>or</em> a <strong>SAS token</strong></td></tr><tr><td>Local filesystem (server-configured)</td><td>Just an absolute path — see below</td></tr></tbody></table><p>Access key and secret key always travel together: for S3, S3-compatible, and GCS storage the dialog requires both, and refuses a connection that supplies one without the other.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Local filesystem</strong> only works if the operator has switched it on. The dialog says so directly — <em>&quot;Local paths must be enabled and scoped by the Wafflebase server&quot;</em> — and a server that has not enabled it answers <em>&quot;Local lakehouse paths are disabled on this server.&quot;</em> When it is enabled, the path must sit inside the one root directory the operator configured.</p><p><strong>Custom endpoints are allowlisted too.</strong> An S3-compatible endpoint, an Azure custom endpoint, or any other non-default endpoint must be an exact match for something the operator has permitted, or saving fails with <em>&quot;… is not allowed by the server.&quot;</em></p></div><h3 id="writing-the-table-path" tabindex="-1">Writing the table path <a class="header-anchor" href="#writing-the-table-path" aria-label="Permalink to &quot;Writing the table path&quot;">​</a></h3><p>The path rules differ by format and by whether you filled in a bucket:</p><ul><li><strong>Iceberg</strong> wants a metadata file — the path must end in <code>.metadata.json</code>.</li><li><strong>Delta</strong> wants the table root, <em>not</em> its <code>_delta_log</code> directory.</li><li>With a <strong>bucket / container</strong> set, give a path relative to it (<code>orders/metadata/v3.metadata.json</code>).</li><li>With <strong>no</strong> bucket, give a fully-qualified URI — <code>s3://…</code> for the S3 backends, <code>gcs://…</code> or <code>gs://…</code> for Google Cloud Storage, <code>az://…</code> for Azure.</li><li>For <strong>local</strong> storage, give an absolute server path (<code>/data/orders</code>) or a <code>file:///</code> URI.</li></ul><p>Paths can&#39;t contain glob characters (<code>*</code>, <code>?</code>, <code>[]</code>, <code>{}</code>), parent-directory segments (<code>..</code>), or control characters.</p><h2 id="reading-the-table" tabindex="-1">Reading the Table <a class="header-anchor" href="#reading-the-table" aria-label="Permalink to &quot;Reading the Table&quot;">​</a></h2><p>There&#39;s no SQL editor and no <strong>Execute</strong> button — a Lakehouse tab reads the table it points at as soon as you open it, and again whenever the time-travel point changes. The first row of the grid holds the column names and each following row is a record.</p><p>The header shows the read&#39;s status on the right: <strong>Loading rows…</strong> while it runs, then something like <code>1204 rows in 812ms</code>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Reads are capped at <strong>10,000 rows</strong>. Past that the status line reads <code>10000 rows (truncated) in …ms</code> — the grid holds the first 10,000 rows and nothing tells you what was left behind, so treat a truncated read as a partial view of the table. A read that takes too long is cut off by a server timeout, 30 seconds by default.</p></div><p>The grid is <strong>read-only</strong>. You can select and copy cells (<strong>⌘/Ctrl+C</strong>), but you can&#39;t edit, sort, or filter them. Like a datasource tab, a Lakehouse tab <strong>can&#39;t be referenced from a formula</strong> in another tab — cross-sheet references resolve only against regular sheet tabs, so <code>Lakehouse1!A1</code> comes back empty rather than reporting an error. To build on the numbers, copy the results into a sheet tab.</p><h2 id="time-travel" tabindex="-1">Time Travel <a class="header-anchor" href="#time-travel" aria-label="Permalink to &quot;Time Travel&quot;">​</a></h2><p>The <strong>Time travel</strong> slider above the grid walks the table&#39;s own commit history, newest on the right.</p><ul><li>Drag it and the label shows the commit you&#39;ve landed on — the commit time in your local timezone, and for Delta the operation that made it (for example <code>2026-08-14, 09:31:02 · WRITE</code>). Releasing the slider re-reads the table at that commit.</li><li>The rightmost stop is the live table, labelled <strong>Latest</strong>. The button beside the slider jumps back to it from anywhere.</li><li>For <strong>Delta Lake</strong> the stops are table versions; for <strong>Apache Iceberg</strong> they are snapshots. Because an Iceberg connection points at one specific <code>.metadata.json</code> file, &quot;latest&quot; means the newest snapshot recorded in <em>that</em> file — which is why the label reads <strong>Latest in configured metadata</strong> rather than plain <strong>Latest</strong> for Iceberg tables.</li><li>History is capped at the <strong>1,000</strong> most recent commits.</li></ul><p>The slider is disabled while the history is still loading, and on a read-only view such as a share link.</p><h3 id="what-gets-saved" tabindex="-1">What gets saved <a class="header-anchor" href="#what-gets-saved" aria-label="Permalink to &quot;What gets saved&quot;">​</a></h3><p>The <strong>commit you pick is saved into the document</strong>, on the tab, and it is shared: a collaborator opening that tab sees the same historical commit you pinned, and reads the table there. Clicking <strong>Latest</strong> clears it again.</p><p>The <strong>rows are not</strong>. Nothing the table returns is written into the document — each person&#39;s grid is filled by their own read, and closing and reopening the tab reads again.</p><p>If somebody pins a commit your history listing doesn&#39;t contain — an old commit that has since aged out of the 1,000 — the slider is replaced by a note reading <code>Snapshot 41… · outside loaded history</code>, and the read still runs against that commit.</p><h2 id="connections-are-shared-with-the-workspace" tabindex="-1">Connections Are Shared With the Workspace <a class="header-anchor" href="#connections-are-shared-with-the-workspace" aria-label="Permalink to &quot;Connections Are Shared With the Workspace&quot;">​</a></h2><p>A saved Lakehouse connection belongs to the <strong>workspace</strong>, not to the person who created it — exactly like a database datasource. Every workspace member can pick it for a tab and read through it, and every read runs against the credentials stored with the connection, whoever triggered it. Workspace membership is the only check: there is no per-connection or per-document permission on top of it.</p><p>The credentials themselves are encrypted before they are stored and are never returned to the browser.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Point a Lakehouse connection at <strong>least-privilege, read-only storage credentials</strong>. Everyone in the workspace shares them, so they should reach only the data you&#39;re willing to show all of them.</p></div><h2 id="good-to-know" tabindex="-1">Good to Know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to Know&quot;">​</a></h2><ul><li>Wafflebase reads the table directly from its metadata; it never sends SQL you wrote, and the connection has no query field.</li><li>Connections are created from the <strong>Select Lakehouse</strong> dialog. There is currently no screen in the app for editing or deleting a Lakehouse connection once it has been saved.</li><li>The tab reads the one table its connection names. Browsing a catalog for other tables is not available in the app.</li></ul>',37)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
